rows=[]
for x in comp+market+insurance:
 oid=x['option_id'];disp,fam,related,why,lim=notes[oid];ids=x.get('evidence_ids',x.get('support_evidence_ids',[]));lookup=einsurance if oid.startswith('OPT-I') else (ecomp if oid.startswith('OPT-C') else emarket)
 found=[lookup[i] for i in ids if i in lookup];urls={z['source_url'] for z in found};lineages={z.get('ownership_cluster') or z.get('ecosystem') or urlparse(z['source_url']).netloc.lower().removeprefix('www.') for z in found}
 rows.append(dict(option_id=oid,title=x.get('title',x.get('direction')),disposition=disp,concept_family=fam,related_option_ids=related,reason=why,evidence_boundary=lim,cited_evidence_records=len(ids),matched_evidence_records=len(found),distinct_cited_source_urls=len(urls),coarse_publisher_clusters=len(lineages),publisher_clusters_are_not_independent_customer_events=True,commercial_winner_selected=False))
